#include "engine.hpp"
static int sequence(const wchar_t* directory){
 std::wstring prefix=directory;if(!prefix.empty()&&prefix.back()!=L'\\'&&prefix.back()!=L'/')prefix+=L'\\';
 WIN32_FIND_DATAW data{};HANDLE search=FindFirstFileW((prefix+L"chat-*.png").c_str(),&data);std::vector<std::wstring> paths;
 if(search!=INVALID_HANDLE_VALUE){do{if(!(data.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY))paths.push_back(prefix+data.cFileName);}while(FindNextFileW(search,&data));FindClose(search);}
 if(paths.empty()){std::puts("{\"error\":\"No chat PNG frames\"}");return 1;}
 std::sort(paths.begin(),paths.end());NativeReader reader;std::vector<double> ms;int hits=0,rows=0,accepted=0;SIZE_T peak_private=0,peak_working=0;
 auto begin=std::chrono::steady_clock::now();FILETIME created,exited,kernel,user;GetProcessTimes(GetCurrentProcess(),&created,&exited,&kernel,&user);
 auto ticks=[](FILETIME t){return (uint64_t(t.dwHighDateTime)<<32)|t.dwLowDateTime;};uint64_t cpu_start=ticks(kernel)+ticks(user);
 for(auto& path:paths){Image image=load_image(path.c_str());if(!image.w)return 2;auto result=reader.recognize(image);ms.push_back(result.milliseconds);hits+=result.cache_hits;rows+=int(result.rows.size());for(auto& row:result.rows)if(!row.item.empty())accepted++;PROCESS_MEMORY_COUNTERS_EX memory{};GetProcessMemoryInfo(GetCurrentProcess(),(PROCESS_MEMORY_COUNTERS*)&memory,sizeof(memory));peak_private=std::max(peak_private,memory.PrivateUsage);peak_working=std::max(peak_working,memory.WorkingSetSize);}
 GetProcessTimes(GetCurrentProcess(),&created,&exited,&kernel,&user);double cpu_ms=(ticks(kernel)+ticks(user)-cpu_start)/10000.0;double wall_ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();
 std::sort(ms.begin(),ms.end());std::printf("{\"frames\":%zu,\"observed_rows\":%d,\"accepted_rows\":%d,\"cache_hits\":%d,\"median_ms\":%.3f,\"p95_ms\":%.3f,\"cpu_ms\":%.3f,\"wall_ms\":%.3f,\"peak_private_bytes\":%llu,\"peak_working_set_bytes\":%llu}\n",paths.size(),rows,accepted,hits,ms[ms.size()/2],ms[std::min(ms.size()-1,size_t(ms.size()*.95))],cpu_ms,wall_ms,(unsigned long long)peak_private,(unsigned long long)peak_working);return 0;
}
int wmain(int argc,wchar_t** argv){
 CoInitializeEx(nullptr,COINIT_MULTITHREADED);
 if(argc==3&&std::wstring(argv[1])==L"--sequence"){int result=sequence(argv[2]);CoUninitialize();return result;}
 if(argc<2){std::puts("BDO Vision native OCR benchmark --image <PNG> [--font-file <TTF>]");return 2;}
 bool ensemble=false;int repeat=1;const wchar_t* input=nullptr;for(int i=1;i<argc;i++){if(std::wstring(argv[i])==L"--image"&&i+1<argc)input=argv[++i];else if(std::wstring(argv[i])==L"--ensemble")ensemble=true;else if(std::wstring(argv[i])==L"--repeat"&&i+1<argc)repeat=std::clamp(_wtoi(argv[++i]),1,10000);else if(std::wstring(argv[i])==L"--color")use_color=true;else if(std::wstring(argv[i])==L"--face"&&i+1<argc)only_face=argv[++i];else if(std::wstring(argv[i])==L"--size"&&i+1<argc)only_height=_wtoi(argv[++i]);else if(std::wstring(argv[i])==L"--weight"&&i+1<argc)only_weight=_wtoi(argv[++i]);else if(std::wstring(argv[i])==L"--font-file"&&i+1<argc)AddFontResourceExW(argv[++i],FR_PRIVATE,nullptr);}
 if(!input)return 2;
 auto start=std::chrono::steady_clock::now();Image im=load_image(input);if(!im.w){std::puts("{\"error\":\"Could not read image\"}");return 1;}if(ensemble){NativeReader reader;FrameRead r;double cold=0,total=0;for(int iteration=0;iteration<repeat;iteration++){r=reader.recognize(im);if(!iteration)cold=r.milliseconds;else total+=r.milliseconds;}std::printf("{\"calibrated\":%s,\"header_error\":%.4f,\"cold_ms\":%.3f,\"warm_ms\":%.3f,\"cache_hits\":%d,\"rows\":[",r.calibrated?"true":"false",r.header_error,cold,repeat>1?total/(repeat-1):r.milliseconds,r.cache_hits);for(size_t i=0;i<r.rows.size();i++){if(i)std::putchar(',');auto& e=r.rows[i];std::printf("{\"item\":\"%s\",\"quantity\":%d,\"name_votes\":%d,\"quantity_votes\":%d}",escape(e.item).c_str(),e.quantity,e.name_votes,e.quantity_votes);}PROCESS_MEMORY_COUNTERS_EX memory{};GetProcessMemoryInfo(GetCurrentProcess(),(PROCESS_MEMORY_COUNTERS*)&memory,sizeof(memory));std::printf("],\"private_bytes\":%llu,\"working_set_bytes\":%llu}\n",(unsigned long long)memory.PrivateUsage,(unsigned long long)memory.WorkingSetSize);CoUninitialize();return 0;}
 auto neutral=text_mask(im,false);auto rows=bands(neutral);Profile p=calibrate(neutral,rows);Raster raster;Profile item_profile=p;item_profile.weight=p.weight;raster.select(item_profile);std::vector<Glyph> atlas;for(char c=32;c<=126;c++)atlas.push_back(raster.draw(std::wstring(1,wchar_t(c)),c));auto full=text_mask(im,use_color);std::vector<Glyph> digits;for(auto& g:atlas)if((g.c>='0'&&g.c<='9')||g.c==' '||g.c=='.'||g.c==',')digits.push_back(g);Catalog catalog;
 std::printf("{\"face\":\"%s\",\"height\":%d,\"weight\":%d,\"italic\":%s,\"prefix_error\":%.4f,\"x\":%d,\"y\":%d,\"prefix_width\":%d,\"rows\":[",escape(utf8(p.face)).c_str(),p.height,p.weight,p.italic?"true":"false",p.error,p.x,p.y,p.prefix_width);
 for(size_t i=0;i<rows.size();i++){auto r=decode(full,atlas,p.x+p.prefix_width,p.y+rows[i].top-rows[0].top);if(i)std::putchar(',');std::string numeric_text;for(size_t z=r.spans.size();z>0;z--)if(r.spans[z-1].c=='x'||r.spans[z-1].c=='X'){
 auto num=decode(full,digits,r.spans[z-1].end,p.y+rows[i].top-rows[0].top,r.spans.back().end);numeric_text=num.text;r.text=r.text.substr(0,z)+numeric_text;break;}
 auto event=extract(r.text,catalog);std::printf("{\"text\":\"%s\",\"cost\":%.2f,\"item\":\"%s\",\"quantity\":%d,\"name_score\":%.4f,\"name_margin\":%.4f}",escape(r.text).c_str(),r.cost,escape(event.item).c_str(),event.quantity,event.score,event.margin);}
 PROCESS_MEMORY_COUNTERS_EX memory{};GetProcessMemoryInfo(GetCurrentProcess(),(PROCESS_MEMORY_COUNTERS*)&memory,sizeof(memory));double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();std::printf("],\"elapsed_ms\":%.3f,\"private_bytes\":%llu}\n",ms,(unsigned long long)memory.PrivateUsage);CoUninitialize();return 0;
}
